// The initial physical plan Catalyst produced BEFORE execution, from estimates.
public class CatalystPlan {
    public int plannedShufflePartitions;   // e.g., a fixed 200 by default
    public String joinStrategy;            // e.g., "SORT_MERGE" (estimated large side)
    public long estimatedRightSideBytes;   // Catalyst's guess

    public CatalystPlan(int plannedShufflePartitions, String joinStrategy,
                        long estimatedRightSideBytes) {
        this.plannedShufflePartitions = plannedShufflePartitions;
        this.joinStrategy = joinStrategy;
        this.estimatedRightSideBytes = estimatedRightSideBytes;
    }
}
