package com.bank.aqe.plan;

import com.bank.aqe.model.BranchTxnCount;
import java.util.logging.Logger;

// Re-optimizes the physical plan at runtime using real statistics.
public class AqeReoptimizer {
    private static final Logger log = Logger.getLogger(AqeReoptimizer.class.getName());

    private static final long SMALL_PARTITION = 1_000_000;     // 1 MB
    private static final long SKEW_THRESHOLD   = 50_000_000;    // 50 MB
    private static final long BROADCAST_LIMIT  = 10_485_760;    // 10 MB

    public CatalystPlan reoptimize(CatalystPlan plan, RuntimeStats stats) {
        log.info("AQE: reading real runtime statistics at the shuffle boundary");

        // 1) Coalesce small partitions into fewer, larger ones.
        int small = 0;
        for (BranchTxnCount p : stats.partitionSizes) {
            if (p.getBytes() < SMALL_PARTITION) small++;
        }
        if (small > 1) {
            int coalesced = stats.partitionSizes.size() - (small - 1);
            final int c = coalesced;
            plan.plannedShufflePartitions = c;
            log.info(() -> "AQE coalesce: merged " + small + " tiny partitions => "
                    + c + " partitions");
        }

        // 2) Skew handling: split any oversized partition.
        for (BranchTxnCount p : stats.partitionSizes) {
            if (p.getBytes() > SKEW_THRESHOLD) {
                log.warning(() -> "AQE skew: partition '" + p.getBranch()
                        + "' is " + p.getBytes() + " bytes — splitting into sub-partitions");
            }
        }

        // 3) Dynamic join switch: if the real right side is small, broadcast it.
        if ("SORT_MERGE".equals(plan.joinStrategy)
                && stats.actualRightSideBytes <= BROADCAST_LIMIT) {
            plan.joinStrategy = "BROADCAST";
            log.info(() -> "AQE join switch: real right side " + stats.actualRightSideBytes
                    + " bytes <= 10MB => switch SORT_MERGE to BROADCAST (no shuffle)");
        }
        return plan;
    }
}
