package com.bank.aqe;

import com.bank.aqe.model.BranchTxnCount;
import com.bank.aqe.plan.*;
import java.util.List;
import java.util.logging.*;

public class AqeDemo {
    private static final Logger log = Logger.getLogger(AqeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new AqeLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // Catalyst's initial plan from estimates: 200 partitions, sort-merge join.
        CatalystPlan plan = new CatalystPlan(200, "SORT_MERGE", 500_000_000L);
        log.info(() -> "Catalyst initial plan: partitions=" + plan.plannedShufflePartitions
                + ", join=" + plan.joinStrategy);

        // Real stats after the shuffle: mostly tiny partitions, one skewed, small right side.
        RuntimeStats stats = new RuntimeStats(List.of(
            new BranchTxnCount("MUM", 800_000),      // tiny
            new BranchTxnCount("DEL", 600_000),      // tiny
            new BranchTxnCount("BLR", 900_000),      // tiny
            new BranchTxnCount("HYD", 120_000_000)   // skewed (month-end spike)
        ), 8_000_000L); // real right side is only 8 MB

        // AQE corrects the plan with facts.
        plan = new AqeReoptimizer().reoptimize(plan, stats);
        log.info(() -> "AQE final plan: partitions=" + plan.plannedShufflePartitions
                + ", join=" + plan.joinStrategy);
    }
}

